using System.Security.Claims;using System.Security.Cryptography;using System.Text;using Microsoft.AspNetCore.Authentication;using Microsoft.AspNetCore.Authentication.Cookies;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace AssetForge.Web.Pages;public class LoginModel(IConfiguration config):PageModel{[BindProperty]public string Username{get;set;}="";[BindProperty]public string Password{get;set;}="";public string? Error{get;set;}public async Task<IActionResult> OnPostAsync(){var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(Password))).ToLowerInvariant();if(!string.Equals(Username,config["Admin:Username"],StringComparison.OrdinalIgnoreCase)||hash!=config["Admin:PasswordSha256"]){Error="Invalid username or password.";return Page();}var identity=new ClaimsIdentity([new Claim(ClaimTypes.Name,Username)],CookieAuthenticationDefaults.AuthenticationScheme);await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(identity));return RedirectToPage("/Index");}}
